package dev.phi.android

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Test

/**
 * Golden values generated by running desktop/electron/src/renderer.ts's
 * algorithm verbatim in node — these lock Kotlin to the desktop rail,
 * glyph for glyph.
 */
class GreekGlyphTest {
    @Test fun poolExcludesPhiAndHas47Letters() {
        assertEquals(47, GreekGlyph.POOL.size)
        assertFalse(GreekGlyph.POOL.contains("Φ"))
        assertFalse(GreekGlyph.POOL.contains("φ"))
    }

    @Test fun canonicalStripsSchemePortAndLocal() {
        assertEquals("ERIS", GreekGlyph.canonicalHostname("eris"))
        // Port stripped.
        assertEquals("ERIS", GreekGlyph.canonicalHostname("http://eris:7070"))
        // .local stripped when trailing.
        assertEquals("ERIS", GreekGlyph.canonicalHostname("eris.local"))
        // Strip order is load-bearing: the port tail protects the .local.
        assertEquals("ERIS.LOCAL", GreekGlyph.canonicalHostname("eris.local:7070"))
        assertEquals("HAUMEA", GreekGlyph.canonicalHostname("HAUMEA"))
    }

    @Test fun goldenGlyphsMatchDesktop() {
        assertEquals("Α", GreekGlyph.forHostname("ERIS"))
        assertEquals("τ", GreekGlyph.forHostname("PLUTO"))
        assertEquals("ρ", GreekGlyph.forHostname("CERES"))
        assertEquals("Ω", GreekGlyph.forHostname("eris.local:7070"))
        assertEquals("Π", GreekGlyph.forHostname("192.0.2.1"))
        assertEquals("Χ", GreekGlyph.forHostname("HAUMEA"))
        assertEquals("θ", GreekGlyph.forHostname("server.example.com"))
    }

    @Test fun sameHostnameSameGlyphAcrossCalls() {
        assertEquals(
            GreekGlyph.forHostname("ERIS"),
            GreekGlyph.forHostname("ERIS"),
        )
    }

    @Test fun collisionsSwapCaseThenMarks() {
        val base = GreekGlyph.forHostname("ERIS")
        val used = mutableSetOf(base)
        val swapped = GreekGlyph.forHostname("ERIS", used)
        assertFalse(swapped == base)
        used += swapped
        val marked = GreekGlyph.forHostname("ERIS", used)
        // Either the case-swap pool is exhausted and marks appear…
        if (marked == base) {
            assertEquals(base + "ʹ", marked)
        }
        // …or a further case variant was chosen; both are legal per renderer.ts.
    }
}
